select r.* from sh_report r left join sh_user u1 on r.user_id = u1.id left join sh_user u2 on r.reported_user_id = u2.id left join sh_idle_item i on r.idle_id = i.id
and r.status = #{status}
and ( CAST(r.id AS CHAR) like concat('%', #{searchValue}, '%') or u1.nickname like concat('%', #{searchValue}, '%') or u2.nickname like concat('%', #{searchValue}, '%') or u1.account_number like concat('%', #{searchValue}, '%') or u2.account_number like concat('%', #{searchValue}, '%') or i.idle_name like concat('%', #{searchValue}, '%') or r.reason like concat('%', #{searchValue}, '%') )
order by r.create_time desc limit #{begin}, #{nums}

select count(*) from sh_report r left join sh_user u1 on r.user_id = u1.id left join sh_user u2 on r.reported_user_id = u2.id left join sh_idle_item i on r.idle_id = i.id
and r.status = #{status}
and ( CAST(r.id AS CHAR) like concat('%', #{searchValue}, '%') or u1.nickname like concat('%', #{searchValue}, '%') or u2.nickname like concat('%', #{searchValue}, '%') or u1.account_number like concat('%', #{searchValue}, '%') or u2.account_number like concat('%', #{searchValue}, '%') or i.idle_name like concat('%', #{searchValue}, '%') or r.reason like concat('%', #{searchValue}, '%') )
